36	final class Utils {
37	  static final Type[] EMPTY_TYPE_ARRAY = new Type[0];
38	
39	  private Utils() {
40	    // No instances.
41	  }
42	
43	  static RuntimeException methodError(Method method, String message, Object... args) {
44	    return methodError(method, null, message, args);
45	  }
46	
47	  @SuppressWarnings("AnnotateFormatMethod")
48	  static RuntimeException methodError(
49	      Method method, @Nullable Throwable cause, String message, Object... args) {
50	    message = String.format(message, args);
51	    return new IllegalArgumentException(
52	        message
53	            + "\n    for method "
54	            + method.getDeclaringClass().getSimpleName()
55	            + "."
56	            + method.getName(),
57	        cause);
58	  }
59	
60	  static RuntimeException parameterError(
61	      Method method, Throwable cause, int p, String message, Object... args) {
62	    String paramDesc = Platform.reflection.describeMethodParameter(method, p);
63	    return methodError(method, cause, message + " (" + paramDesc + ")", args);
64	  }
65	
66	  static RuntimeException parameterError(Method method, int p, String message, Object... args) {
67	    String paramDesc = Platform.reflection.describeMethodParameter(method, p);
68	    return methodError(method, message + " (" + paramDesc + ")", args);
69	  }
70	
71	  static Class<?> getRawType(Type type) {
72	    Objects.requireNonNull(type, "type == null");
73	
74	    if (type instanceof Class<?>) {
75	      // Type is a normal class.
76	      return (Class<?>) type;
77	    }
78	    if (type instanceof ParameterizedType) {
79	      ParameterizedType parameterizedType = (ParameterizedType) type;
80	
81	      // I'm not exactly sure why getRawType() returns Type instead of Class. Neal isn't either but
82	      // suspects some pathological case related to nested classes exists.
83	      Type rawType = parameterizedType.getRawType();
84	      if (!(rawType instanceof Class)) throw new IllegalArgumentException();
85	      return (Class<?>) rawType;
86	    }
87	    if (type instanceof GenericArrayType) {
88	      Type componentType = ((GenericArrayType) type).getGenericComponentType();
89	      return Array.newInstance(getRawType(componentType), 0).getClass();
90	    }
91	    if (type instanceof TypeVariable) {
92	      // We could use the variable's bounds, but that won't work if there are multiple. Having a raw
93	      // type that's more general than necessary is okay.
94	      return Object.class;
95	    }
96	    if (type instanceof WildcardType) {
97	      return getRawType(((WildcardType) type).getUpperBounds()[0]);
98	    }
99	
100	    throw new IllegalArgumentException(
101	        "Expected a Class, ParameterizedType, or "
102	            + "GenericArrayType, but <"
103	            + type
104	            + "> is of type "
105	            + type.getClass().getName());
106	  }
107	
108	  /** Returns true if {@code a} and {@code b} are equal. */
109	  static boolean equals(Type a, Type b) {
110	    if (a == b) {
111	      return true; // Also handles (a == null && b == null).
112	
113	    } else if (a instanceof Class) {
114	      return a.equals(b); // Class already specifies equals().
115	
116	    } else if (a instanceof ParameterizedType) {
117	      if (!(b instanceof ParameterizedType)) return false;
118	      ParameterizedType pa = (ParameterizedType) a;
119	      ParameterizedType pb = (ParameterizedType) b;
120	      Object ownerA = pa.getOwnerType();
121	      Object ownerB = pb.getOwnerType();
122	      boolean ownersAreEqual = ownerA == ownerB || (ownerA != null && ownerA.equals(ownerB));
123	      boolean rawTypesAreEqual = pa.getRawType().equals(pb.getRawType());
124	      boolean typeArgumentsAreEqual =
125	          Arrays.equals(pa.getActualTypeArguments(), pb.getActualTypeArguments());
126	
127	      return ownersAreEqual && rawTypesAreEqual && typeArgumentsAreEqual;
128	
129	    } else if (a instanceof GenericArrayType) {
130	      if (!(b instanceof GenericArrayType)) return false;
131	      GenericArrayType ga = (GenericArrayType) a;
132	      GenericArrayType gb = (GenericArrayType) b;
133	      return equals(ga.getGenericComponentType(), gb.getGenericComponentType());
134	
135	    } else if (a instanceof WildcardType) {
136	      if (!(b instanceof WildcardType)) return false;
137	      WildcardType wa = (WildcardType) a;
138	      WildcardType wb = (WildcardType) b;
139	      return Arrays.equals(wa.getUpperBounds(), wb.getUpperBounds())
140	          && Arrays.equals(wa.getLowerBounds(), wb.getLowerBounds());
141	
142	    } else if (a instanceof TypeVariable) {
143	      if (!(b instanceof TypeVariable)) return false;
144	      TypeVariable<?> va = (TypeVariable<?>) a;
145	      TypeVariable<?> vb = (TypeVariable<?>) b;
146	      return va.getGenericDeclaration() == vb.getGenericDeclaration()
147	          && va.getName().equals(vb.getName());
148	
149	    } else {
150	      return false; // This isn't a type we support!
151	    }
152	  }
153	
154	  /**
155	   * Returns the generic supertype for {@code supertype}. For example, given a class {@code
156	   * IntegerSet}, the result for when supertype is {@code Set.class} is {@code Set<Integer>} and the
157	   * result when the supertype is {@code Collection.class} is {@code Collection<Integer>}.
158	   */
159	  static Type getGenericSupertype(Type context, Class<?> rawType, Class<?> toResolve) {
160	    if (toResolve == rawType) return context;
161	
162	    // We skip searching through interfaces if unknown is an interface.
163	    if (toResolve.isInterface()) {
164	      Class<?>[] interfaces = rawType.getInterfaces();
165	      for (int i = 0, length = interfaces.length; i < length; i++) {
166	        if (interfaces[i] == toResolve) {
167	          return rawType.getGenericInterfaces()[i];
168	        } else if (toResolve.isAssignableFrom(interfaces[i])) {
169	          return getGenericSupertype(rawType.getGenericInterfaces()[i], interfaces[i], toResolve);
170	        }
171	      }
172	    }
173	
174	    // Check our supertypes.
175	    if (!rawType.isInterface()) {
176	      while (rawType != Object.class) {
177	        Class<?> rawSupertype = rawType.getSuperclass();
178	        if (rawSupertype == toResolve) {
179	          return rawType.getGenericSuperclass();
180	        } else if (toResolve.isAssignableFrom(rawSupertype)) {
181	          return getGenericSupertype(rawType.getGenericSuperclass(), rawSupertype, toResolve);
182	        }
183	        rawType = rawSupertype;
184	      }
185	    }
186	
187	    // We can't resolve this further.
188	    return toResolve;
189	  }
190	
191	  private static int indexOf(Object[] array, Object toFind) {
192	    for (int i = 0; i < array.length; i++) {
193	      if (toFind.equals(array[i])) return i;
194	    }
195	    throw new NoSuchElementException();
196	  }
197	
198	  static String typeToString(Type type) {
199	    return type instanceof Class ? ((Class<?>) type).getName() : type.toString();
200	  }
201	
202	  /**
203	   * Returns the generic form of {@code supertype}. For example, if this is {@code
204	   * ArrayList<String>}, this returns {@code Iterable<String>} given the input {@code
205	   * Iterable.class}.
206	   *
207	   * @param supertype a superclass of, or interface implemented by, this.
208	   */
209	  static Type getSupertype(Type context, Class<?> contextRawType, Class<?> supertype) {
210	    if (!supertype.isAssignableFrom(contextRawType)) throw new IllegalArgumentException();
211	    return resolve(
212	        context, contextRawType, getGenericSupertype(context, contextRawType, supertype));
213	  }
214	
215	  static Type resolve(Type context, Class<?> contextRawType, Type toResolve) {
216	    // This implementation is made a little more complicated in an attempt to avoid object-creation.
217	    while (true) {
218	      if (toResolve instanceof TypeVariable) {
219	        TypeVariable<?> typeVariable = (TypeVariable<?>) toResolve;
220	        toResolve = resolveTypeVariable(context, contextRawType, typeVariable);
221	        if (toResolve == typeVariable) {
222	          return toResolve;
223	        }
224	
225	      } else if (toResolve instanceof Class && ((Class<?>) toResolve).isArray()) {
226	        Class<?> original = (Class<?>) toResolve;
227	        Type componentType = original.getComponentType();
228	        Type newComponentType = resolve(context, contextRawType, componentType);
229	        return componentType == newComponentType
230	            ? original
231	            : new GenericArrayTypeImpl(newComponentType);
232	
233	      } else if (toResolve instanceof GenericArrayType) {
234	        GenericArrayType original = (GenericArrayType) toResolve;
235	        Type componentType = original.getGenericComponentType();
236	        Type newComponentType = resolve(context, contextRawType, componentType);
237	        return componentType == newComponentType
238	            ? original
239	            : new GenericArrayTypeImpl(newComponentType);
240	
241	      } else if (toResolve instanceof ParameterizedType) {
242	        ParameterizedType original = (ParameterizedType) toResolve;
243	        Type ownerType = original.getOwnerType();
244	        Type newOwnerType = resolve(context, contextRawType, ownerType);
245	        boolean changed = newOwnerType != ownerType;
246	
247	        Type[] args = original.getActualTypeArguments();
248	        for (int t = 0, length = args.length; t < length; t++) {
249	          Type resolvedTypeArgument = resolve(context, contextRawType, args[t]);
250	          if (resolvedTypeArgument != args[t]) {
251	            if (!changed) {
252	              args = args.clone();
253	              changed = true;
254	            }
255	            args[t] = resolvedTypeArgument;
256	          }
257	        }
258	
259	        return changed
260	            ? new ParameterizedTypeImpl(newOwnerType, original.getRawType(), args)
261	            : original;
262	
263	      } else if (toResolve instanceof WildcardType) {
264	        WildcardType original = (WildcardType) toResolve;
265	        Type[] originalLowerBound = original.getLowerBounds();
266	        Type[] originalUpperBound = original.getUpperBounds();
267	
268	        if (originalLowerBound.length == 1) {
269	          Type lowerBound = resolve(context, contextRawType, originalLowerBound[0]);
270	          if (lowerBound != originalLowerBound[0]) {
271	            return new WildcardTypeImpl(new Type[] {Object.class}, new Type[] {lowerBound});
272	          }
273	        } else if (originalUpperBound.length == 1) {
274	          Type upperBound = resolve(context, contextRawType, originalUpperBound[0]);
275	          if (upperBound != originalUpperBound[0]) {
276	            return new WildcardTypeImpl(new Type[] {upperBound}, EMPTY_TYPE_ARRAY);
277	          }
278	        }
279	        return original;
280	
281	      } else {
282	        return toResolve;
283	      }
284	    }
285	  }
286	
287	  private static Type resolveTypeVariable(
288	      Type context, Class<?> contextRawType, TypeVariable<?> unknown) {
289	    Class<?> declaredByRaw = declaringClassOf(unknown);
290	
291	    // We can't reduce this further.
292	    if (declaredByRaw == null) return unknown;
293	
294	    Type declaredBy = getGenericSupertype(context, contextRawType, declaredByRaw);
295	    if (declaredBy instanceof ParameterizedType) {
296	      int index = indexOf(declaredByRaw.getTypeParameters(), unknown);
297	      return ((ParameterizedType) declaredBy).getActualTypeArguments()[index];
298	    }
299	
300	    return unknown;
301	  }
302	
303	  /**
304	   * Returns the declaring class of {@code typeVariable}, or {@code null} if it was not declared by
305	   * a class.
306	   */
307	  private static @Nullable Class<?> declaringClassOf(TypeVariable<?> typeVariable) {
308	    GenericDeclaration genericDeclaration = typeVariable.getGenericDeclaration();
309	    return genericDeclaration instanceof Class ? (Class<?>) genericDeclaration : null;
310	  }
311	
312	  static void checkNotPrimitive(Type type) {
313	    if (type instanceof Class<?> && ((Class<?>) type).isPrimitive()) {
314	      throw new IllegalArgumentException();
315	    }
316	  }
317	
318	  /** Returns true if {@code annotations} contains an instance of {@code cls}. */
319	  static boolean isAnnotationPresent(Annotation[] annotations, Class<? extends Annotation> cls) {
320	    for (Annotation annotation : annotations) {
321	      if (cls.isInstance(annotation)) {
322	        return true;
323	      }
324	    }
325	    return false;
326	  }
