448	  private static final class GenericArrayTypeImpl implements GenericArrayType {
449	    private final Type componentType;
450	
451	    GenericArrayTypeImpl(Type componentType) {
452	      this.componentType = componentType;
453	    }
454	
455	    @Override
456	    public Type getGenericComponentType() {
457	      return componentType;
458	    }
459	
460	    @Override
461	    public boolean equals(Object o) {
462	      return o instanceof GenericArrayType && Utils.equals(this, (GenericArrayType) o);
463	    }
464	
465	    @Override
466	    public int hashCode() {
467	      return componentType.hashCode();
468	    }
469	
470	    @Override
471	    public String toString() {
472	      return typeToString(componentType) + "[]";
473	    }
474	  }
