476	  /**
477	   * The WildcardType interface supports multiple upper bounds and multiple lower bounds. We only
478	   * support what the Java 6 language needs - at most one bound. If a lower bound is set, the upper
479	   * bound must be Object.class.
480	   */
481	  private static final class WildcardTypeImpl implements WildcardType {
482	    private final Type upperBound;
483	    private final @Nullable Type lowerBound;
484	
485	    WildcardTypeImpl(Type[] upperBounds, Type[] lowerBounds) {
486	      if (lowerBounds.length > 1) throw new IllegalArgumentException();
487	      if (upperBounds.length != 1) throw new IllegalArgumentException();
488	
489	      if (lowerBounds.length == 1) {
490	        if (lowerBounds[0] == null) throw new NullPointerException();
491	        checkNotPrimitive(lowerBounds[0]);
492	        if (upperBounds[0] != Object.class) throw new IllegalArgumentException();
493	        this.lowerBound = lowerBounds[0];
494	        this.upperBound = Object.class;
495	      } else {
496	        if (upperBounds[0] == null) throw new NullPointerException();
497	        checkNotPrimitive(upperBounds[0]);
498	        this.lowerBound = null;
499	        this.upperBound = upperBounds[0];
500	      }
501	    }
502	
503	    @Override
504	    public Type[] getUpperBounds() {
505	      return new Type[] {upperBound};
506	    }
507	
508	    @Override
509	    public Type[] getLowerBounds() {
510	      return lowerBound != null ? new Type[] {lowerBound} : EMPTY_TYPE_ARRAY;
511	    }
512	
513	    @Override
514	    public boolean equals(Object other) {
515	      return other instanceof WildcardType && Utils.equals(this, (WildcardType) other);
516	    }
517	
518	    @Override
519	    public int hashCode() {
520	      // This equals Arrays.hashCode(getLowerBounds()) ^ Arrays.hashCode(getUpperBounds()).
521	      return (lowerBound != null ? 31 + lowerBound.hashCode() : 1) ^ (31 + upperBound.hashCode());
522	    }
523	
524	    @Override
525	    public String toString() {
526	      if (lowerBound != null) return "? super " + typeToString(lowerBound);
527	      if (upperBound == Object.class) return "?";
528	      return "? extends " + typeToString(upperBound);
529	    }
530	  }
