99	  okhttp3.Request create(@Nullable Object instance, Object[] args) throws IOException {
100	    @SuppressWarnings("unchecked") // It is an error to invoke a method with the wrong arg types.
101	    ParameterHandler<Object>[] handlers = (ParameterHandler<Object>[]) parameterHandlers;
102	
103	    int argumentCount = args.length;
104	    if (argumentCount != handlers.length) {
105	      throw new IllegalArgumentException(
106	          "Argument count ("
107	              + argumentCount
108	              + ") doesn't match expected count ("
109	              + handlers.length
110	              + ")");
111	    }
112	
113	    RequestBuilder requestBuilder =
114	        new RequestBuilder(
115	            httpMethod,
116	            baseUrl,
117	            relativeUrl,
118	            headers,
119	            contentType,
120	            hasBody,
121	            isFormEncoded,
122	            isMultipart);
123	
124	    if (isKotlinSuspendFunction) {
125	      // The Continuation is the last parameter and the handlers array contains null at that index.
126	      argumentCount--;
127	    }
128	
129	    List<Object> argumentList = new ArrayList<>(argumentCount);
130	    for (int p = 0; p < argumentCount; p++) {
131	      argumentList.add(args[p]);
132	      handlers[p].apply(requestBuilder, args[p]);
133	    }
134	
135	    return requestBuilder
136	        .get()
137	        .tag(Invocation.class, new Invocation(service, instance, method, argumentList, relativeUrl))
138	        .build();
139	  }
140	
141	  /**
142	   * Inspects the annotations on an interface method to construct a reusable service method. This
143	   * requires potentially-expensive reflection so it is best to build each service method only once
144	   * and reuse it. Builders cannot be reused.
145	   */
146	  static final class Builder {
147	    // Upper and lower characters, digits, underscores, and hyphens, starting with a character.
148	    private static final String PARAM = "[a-zA-Z][a-zA-Z0-9_-]*";
149	    private static final Pattern PARAM_URL_REGEX = Pattern.compile("\\{(" + PARAM + ")\\}");
150	    private static final Pattern PARAM_NAME_REGEX = Pattern.compile(PARAM);
151	
152	    final Retrofit retrofit;
153	    final Class<?> service;
154	    final Method method;
155	    final Annotation[] methodAnnotations;
156	    final Annotation[][] parameterAnnotationsArray;
157	    final Type[] parameterTypes;
158	
159	    boolean gotField;
160	    boolean gotPart;
161	    boolean gotBody;
162	    boolean gotPath;
163	    boolean gotQuery;
164	    boolean gotQueryName;
165	    boolean gotQueryMap;
166	    boolean gotUrl;
167	    @Nullable String httpMethod;
168	    boolean hasBody;
169	    boolean isFormEncoded;
170	    boolean isMultipart;
171	    @Nullable String relativeUrl;
172	    @Nullable Headers headers;
173	    @Nullable MediaType contentType;
174	    @Nullable Set<String> relativeUrlParamNames;
175	    @Nullable ParameterHandler<?>[] parameterHandlers;
176	    boolean isKotlinSuspendFunction;
177	
178	    Builder(Retrofit retrofit, Class<?> service, Method method) {
179	      this.retrofit = retrofit;
180	      this.service = service;
181	      this.method = method;
182	      this.methodAnnotations = method.getAnnotations();
183	      this.parameterTypes = method.getGenericParameterTypes();
184	      this.parameterAnnotationsArray = method.getParameterAnnotations();
185	    }
186	
187	    RequestFactory build() {
188	      for (Annotation annotation : methodAnnotations) {
189	        parseMethodAnnotation(annotation);
190	      }
191	
192	      if (httpMethod == null) {
193	        throw methodError(method, "HTTP method annotation is required (e.g., @GET, @POST, etc.).");
194	      }
195	
196	      if (!hasBody) {
197	        if (isMultipart) {
198	          throw methodError(
199	              method,
200	              "Multipart can only be specified on HTTP methods with request body (e.g., @POST).");
201	        }
202	        if (isFormEncoded) {
203	          throw methodError(
204	              method,
205	              "FormUrlEncoded can only be specified on HTTP methods with "
206	                  + "request body (e.g., @POST).");
207	        }
208	      }
209	
210	      int parameterCount = parameterAnnotationsArray.length;
211	      parameterHandlers = new ParameterHandler<?>[parameterCount];
212	      for (int p = 0, lastParameter = parameterCount - 1; p < parameterCount; p++) {
213	        parameterHandlers[p] =
214	            parseParameter(p, parameterTypes[p], parameterAnnotationsArray[p], p == lastParameter);
215	      }
216	
217	      if (relativeUrl == null && !gotUrl) {
218	        throw methodError(method, "Missing either @%s URL or @Url parameter.", httpMethod);
219	      }
220	      if (!isFormEncoded && !isMultipart && !hasBody && gotBody) {
221	        throw methodError(method, "Non-body HTTP method cannot contain @Body.");
222	      }
223	      if (isFormEncoded && !gotField) {
224	        throw methodError(method, "Form-encoded method must contain at least one @Field.");
225	      }
226	      if (isMultipart && !gotPart) {
227	        throw methodError(method, "Multipart method must contain at least one @Part.");
228	      }
229	
230	      return new RequestFactory(this);
231	    }
232	
233	    private void parseMethodAnnotation(Annotation annotation) {
234	      if (annotation instanceof DELETE) {
235	        parseHttpMethodAndPath("DELETE", ((DELETE) annotation).value(), false);
236	      } else if (annotation instanceof GET) {
237	        parseHttpMethodAndPath("GET", ((GET) annotation).value(), false);
238	      } else if (annotation instanceof HEAD) {
239	        parseHttpMethodAndPath("HEAD", ((HEAD) annotation).value(), false);
240	      } else if (annotation instanceof PATCH) {
241	        parseHttpMethodAndPath("PATCH", ((PATCH) annotation).value(), true);
242	      } else if (annotation instanceof POST) {
243	        parseHttpMethodAndPath("POST", ((POST) annotation).value(), true);
244	      } else if (annotation instanceof PUT) {
245	        parseHttpMethodAndPath("PUT", ((PUT) annotation).value(), true);
246	      } else if (annotation instanceof OPTIONS) {
247	        parseHttpMethodAndPath("OPTIONS", ((OPTIONS) annotation).value(), false);
248	      } else if (annotation instanceof QUERY) {
249	        parseHttpMethodAndPath("QUERY", ((QUERY) annotation).value(), true);
250	      } else if (annotation instanceof HTTP) {
251	        HTTP http = (HTTP) annotation;
252	        parseHttpMethodAndPath(http.method(), http.path(), http.hasBody());
253	      } else if (annotation instanceof retrofit2.http.Headers) {
254	        retrofit2.http.Headers headers = (retrofit2.http.Headers) annotation;
255	        String[] headersToParse = headers.value();
256	        if (headersToParse.length == 0) {
257	          throw methodError(method, "@Headers annotation is empty.");
258	        }
259	        this.headers = parseHeaders(headersToParse, headers.allowUnsafeNonAsciiValues());
260	      } else if (annotation instanceof Multipart) {
261	        if (isFormEncoded) {
262	          throw methodError(method, "Only one encoding annotation is allowed.");
263	        }
264	        isMultipart = true;
265	      } else if (annotation instanceof FormUrlEncoded) {
266	        if (isMultipart) {
267	          throw methodError(method, "Only one encoding annotation is allowed.");
268	        }
269	        isFormEncoded = true;
270	      }
271	    }
272	
273	    private void parseHttpMethodAndPath(String httpMethod, String value, boolean hasBody) {
274	      if (this.httpMethod != null) {
275	        throw methodError(
276	            method,
277	            "Only one HTTP method is allowed. Found: %s and %s.",
278	            this.httpMethod,
279	            httpMethod);
280	      }
281	      this.httpMethod = httpMethod;
282	      this.hasBody = hasBody;
283	
284	      if (value.isEmpty()) {
285	        return;
286	      }
287	
288	      // Get the relative URL path and existing query string, if present.
289	      int question = value.indexOf('?');
290	      if (question != -1 && question < value.length() - 1) {
291	        // Ensure the query string does not have any named parameters.
292	        String queryParams = value.substring(question + 1);
293	        Matcher queryParamMatcher = PARAM_URL_REGEX.matcher(queryParams);
294	        if (queryParamMatcher.find()) {
295	          throw methodError(
296	              method,
297	              "URL query string \"%s\" must not have replace block. "
298	                  + "For dynamic query parameters use @Query.",
299	              queryParams);
300	        }
301	      }
302	
303	      this.relativeUrl = value;
304	      this.relativeUrlParamNames = parsePathParameters(value);
305	    }
306	
307	    private Headers parseHeaders(String[] headers, boolean allowUnsafeNonAsciiValues) {
308	      Headers.Builder builder = new Headers.Builder();
309	      for (String header : headers) {
310	        int colon = header.indexOf(':');
311	        if (colon == -1 || colon == 0 || colon == header.length() - 1) {
312	          throw methodError(
313	              method, "@Headers value must be in the form \"Name: Value\". Found: \"%s\"", header);
314	        }
315	        String headerName = header.substring(0, colon);
316	        String headerValue = header.substring(colon + 1).trim();
317	        if ("Content-Type".equalsIgnoreCase(headerName)) {
318	          try {
319	            contentType = MediaType.get(headerValue);
320	          } catch (IllegalArgumentException e) {
321	            throw methodError(method, e, "Malformed content type: %s", headerValue);
322	          }
323	        } else if (allowUnsafeNonAsciiValues) {
324	          builder.addUnsafeNonAscii(headerName, headerValue);
325	        } else {
326	          builder.add(headerName, headerValue);
327	        }
328	      }
329	      return builder.build();
330	    }
331	
332	    private @Nullable ParameterHandler<?> parseParameter(
333	        int p, Type parameterType, @Nullable Annotation[] annotations, boolean allowContinuation) {
334	      ParameterHandler<?> result = null;
335	      if (annotations != null) {
336	        for (Annotation annotation : annotations) {
337	          ParameterHandler<?> annotationAction =
338	              parseParameterAnnotation(p, parameterType, annotations, annotation);
339	
340	          if (annotationAction == null) {
341	            continue;
342	          }
343	
344	          if (result != null) {
345	            throw parameterError(
346	                method, p, "Multiple Retrofit annotations found, only one allowed.");
347	          }
348	
349	          result = annotationAction;
350	        }
351	      }
352	
353	      if (result == null) {
354	        if (allowContinuation) {
355	          try {
356	            if (Utils.getRawType(parameterType) == Continuation.class) {
357	              isKotlinSuspendFunction = true;
358	              return null;
359	            }
360	          } catch (NoClassDefFoundError ignored) {
361	            // Ignored
362	          }
363	        }
364	        throw parameterError(method, p, "No Retrofit annotation found.");
365	      }
366	
367	      return result;
368	    }
