370	    @Nullable
371	    private ParameterHandler<?> parseParameterAnnotation(
372	        int p, Type type, Annotation[] annotations, Annotation annotation) {
373	      if (annotation instanceof Url) {
374	        validateResolvableType(p, type);
375	        if (gotUrl) {
376	          throw parameterError(method, p, "Multiple @Url method annotations found.");
377	        }
378	        if (gotPath) {
379	          throw parameterError(method, p, "@Path parameters may not be used with @Url.");
380	        }
381	        if (gotQuery) {
382	          throw parameterError(method, p, "A @Url parameter must not come after a @Query.");
383	        }
384	        if (gotQueryName) {
385	          throw parameterError(method, p, "A @Url parameter must not come after a @QueryName.");
386	        }
387	        if (gotQueryMap) {
388	          throw parameterError(method, p, "A @Url parameter must not come after a @QueryMap.");
389	        }
390	        if (relativeUrl != null) {
391	          throw parameterError(method, p, "@Url cannot be used with @%s URL", httpMethod);
392	        }
393	
394	        gotUrl = true;
395	
396	        if (type == HttpUrl.class
397	            || type == String.class
398	            || type == URI.class
399	            || (type instanceof Class && "android.net.Uri".equals(((Class<?>) type).getName()))) {
400	          return new ParameterHandler.RelativeUrl(method, p);
401	        } else {
402	          throw parameterError(
403	              method,
404	              p,
405	              "@Url must be okhttp3.HttpUrl, String, java.net.URI, or android.net.Uri type.");
406	        }
407	
408	      } else if (annotation instanceof Path) {
409	        validateResolvableType(p, type);
410	        if (gotQuery) {
