27	abstract class ParameterHandler<T> {
28	  abstract void apply(RequestBuilder builder, @Nullable T value) throws IOException;
29	
30	  final ParameterHandler<Iterable<T>> iterable() {
31	    return new ParameterHandler<Iterable<T>>() {
32	      @Override
33	      void apply(RequestBuilder builder, @Nullable Iterable<T> values) throws IOException {
34	        if (values == null) return; // Skip null values.
35	
36	        for (T value : values) {
37	          ParameterHandler.this.apply(builder, value);
38	        }
39	      }
40	    };
41	  }
42	
43	  final ParameterHandler<Object> array() {
44	    return new ParameterHandler<Object>() {
45	      @Override
46	      void apply(RequestBuilder builder, @Nullable Object values) throws IOException {
47	        if (values == null) return; // Skip null values.
48	
49	        for (int i = 0, size = Array.getLength(values); i < size; i++) {
50	          //noinspection unchecked
51	          ParameterHandler.this.apply(builder, (T) Array.get(values, i));
52	        }
53	      }
54	    };
55	  }
