61	    RelativeUrl(Method method, int p) {
62	      this.method = method;
63	      this.p = p;
64	    }
65	
66	    @Override
67	    void apply(RequestBuilder builder, @Nullable Object value) {
68	      if (value == null) {
69	        throw Utils.parameterError(method, p, "@Url parameter is null.");
70	      }
71	      builder.setRelativeUrl(value);
72	    }
73	  }
