75	  static final class Header<T> extends ParameterHandler<T> {
76	    private final String name;
77	    private final Converter<T, String> valueConverter;
78	    private final boolean allowUnsafeNonAsciiValues;
79	
80	    Header(String name, Converter<T, String> valueConverter, boolean allowUnsafeNonAsciiValues) {
81	      this.name = Objects.requireNonNull(name, "name == null");
82	      this.valueConverter = valueConverter;
83	      this.allowUnsafeNonAsciiValues = allowUnsafeNonAsciiValues;
84	    }
85	
86	    @Override
87	    void apply(RequestBuilder builder, @Nullable T value) throws IOException {
88	      if (value == null) return; // Skip null values.
89	
90	      String headerValue = valueConverter.convert(value);
91	      if (headerValue == null) return; // Skip converted but null values.
92	
93	      builder.addHeader(name, headerValue, allowUnsafeNonAsciiValues);
94	    }
95	  }
