209	  static final class HeaderMap<T> extends ParameterHandler<Map<String, T>> {
210	    private final Method method;
211	    private final int p;
212	    private final Converter<T, String> valueConverter;
213	    private final boolean allowUnsafeNonAsciiValues;
214	
215	    HeaderMap(
216	        Method method,
217	        int p,
218	        Converter<T, String> valueConverter,
219	        boolean allowUnsafeNonAsciiValues) {
220	      this.method = method;
221	      this.p = p;
222	      this.valueConverter = valueConverter;
223	      this.allowUnsafeNonAsciiValues = allowUnsafeNonAsciiValues;
224	    }
225	
226	    @Override
227	    void apply(RequestBuilder builder, @Nullable Map<String, T> value) throws IOException {
228	      if (value == null) {
