33	final class OkHttpCall<T> implements Call<T> {
34	  private final RequestFactory requestFactory;
35	  private final Object instance;
36	  private final Object[] args;
37	  private final okhttp3.Call.Factory callFactory;
38	  private final Converter<ResponseBody, T> responseConverter;
39	
40	  private volatile boolean canceled;
41	
42	  @GuardedBy("this")
43	  private @Nullable okhttp3.Call rawCall;
44	
45	  @GuardedBy("this") // Either a RuntimeException, non-fatal Error, or IOException.
46	  private @Nullable Throwable creationFailure;
47	
48	  @GuardedBy("this")
49	  private boolean executed;
50	
51	  OkHttpCall(
52	      RequestFactory requestFactory,
53	      Object instance,
54	      Object[] args,
55	      okhttp3.Call.Factory callFactory,
56	      Converter<ResponseBody, T> responseConverter) {
57	    this.requestFactory = requestFactory;
58	    this.instance = instance;
59	    this.args = args;
60	    this.callFactory = callFactory;
61	    this.responseConverter = responseConverter;
62	  }
63	
64	  @SuppressWarnings("CloneDoesntCallSuperClone") // We are a final type & this saves clearing state.
65	  @Override
66	  public OkHttpCall<T> clone() {
67	    return new OkHttpCall<>(requestFactory, instance, args, callFactory, responseConverter);
68	  }
69	
70	  @Override
71	  public synchronized Request request() {
72	    try {
73	      return getRawCall().request();
74	    } catch (IOException e) {
75	      throw new RuntimeException("Unable to create request.", e);
76	    }
77	  }
78	
79	  @Override
80	  public synchronized Timeout timeout() {
81	    try {
82	      return getRawCall().timeout();
83	    } catch (IOException e) {
84	      throw new RuntimeException("Unable to create call.", e);
85	    }
86	  }
87	
88	  /**
89	   * Returns the raw call, initializing it if necessary. Throws if initializing the raw call throws,
90	   * or has thrown in previous attempts to create it.
91	   */
92	  @GuardedBy("this")
93	  private okhttp3.Call getRawCall() throws IOException {
94	    okhttp3.Call call = rawCall;
95	    if (call != null) return call;
96	
97	    // Re-throw previous failures if this isn't the first attempt.
98	    if (creationFailure != null) {
99	      if (creationFailure instanceof IOException) {
100	        throw (IOException) creationFailure;
101	      } else if (creationFailure instanceof RuntimeException) {
102	        throw (RuntimeException) creationFailure;
103	      } else {
104	        throw (Error) creationFailure;
105	      }
106	    }
107	
108	    // Create and remember either the success or the failure.
109	    try {
110	      return rawCall = createRawCall();
111	    } catch (RuntimeException | Error | IOException e) {
112	      throwIfFatal(e); // Do not assign a fatal error to creationFailure.
113	      creationFailure = e;
114	      throw e;
115	    }
116	  }
117	
118	  @Override
119	  public void enqueue(final Callback<T> callback) {
120	    Objects.requireNonNull(callback, "callback == null");
121	
122	    okhttp3.Call call;
123	    Throwable failure;
124	
125	    synchronized (this) {
126	      if (executed) throw new IllegalStateException("Already executed.");
127	      executed = true;
128	
129	      call = rawCall;
130	      failure = creationFailure;
131	      if (call == null && failure == null) {
132	        try {
133	          call = rawCall = createRawCall();
134	        } catch (Throwable t) {
135	          throwIfFatal(t);
136	          failure = creationFailure = t;
137	        }
138	      }
139	    }
140	
141	    if (failure != null) {
142	      callback.onFailure(this, failure);
143	      return;
144	    }
145	
146	    if (canceled) {
147	      call.cancel();
148	    }
149	
150	    call.enqueue(
151	        new okhttp3.Callback() {
152	          @Override
153	          public void onResponse(okhttp3.Call call, okhttp3.Response rawResponse) {
154	            Response<T> response;
155	            try {
156	              response = parseResponse(rawResponse);
157	            } catch (Throwable e) {
158	              throwIfFatal(e);
159	              callFailure(e);
160	              return;
161	            }
162	
163	            try {
164	              callback.onResponse(OkHttpCall.this, response);
165	            } catch (Throwable t) {
166	              throwIfFatal(t);
167	              t.printStackTrace(); // TODO this is not great
168	            }
169	          }
170	
171	          @Override
172	          public void onFailure(okhttp3.Call call, IOException e) {
173	            callFailure(e);
174	          }
175	
176	          private void callFailure(Throwable e) {
177	            try {
178	              callback.onFailure(OkHttpCall.this, e);
179	            } catch (Throwable t) {
180	              throwIfFatal(t);
181	              t.printStackTrace(); // TODO this is not great
182	            }
183	          }
184	        });
185	  }
186	
187	  @Override
188	  public synchronized boolean isExecuted() {
189	    return executed;
190	  }
191	
192	  @Override
193	  public Response<T> execute() throws IOException {
194	    okhttp3.Call call;
195	
196	    synchronized (this) {
197	      if (executed) throw new IllegalStateException("Already executed.");
198	      executed = true;
199	
200	      call = getRawCall();
201	    }
202	
203	    if (canceled) {
204	      call.cancel();
205	    }
206	
207	    return parseResponse(call.execute());
208	  }
209	
210	  private okhttp3.Call createRawCall() throws IOException {
211	    okhttp3.Call call = callFactory.newCall(requestFactory.create(instance, args));
212	    if (call == null) {
213	      throw new NullPointerException("Call.Factory returned null.");
214	    }
215	    return call;
216	  }
217	
218	  Response<T> parseResponse(okhttp3.Response rawResponse) throws IOException {
219	    ResponseBody rawBody = rawResponse.body();
220	
221	    // Remove the body's source (the only stateful object) so we can pass the response along.
222	    rawResponse =
223	        rawResponse
224	            .newBuilder()
225	            .body(new NoContentResponseBody(rawBody.contentType(), rawBody.contentLength()))
226	            .build();
227	
228	    int code = rawResponse.code();
229	    if (code < 200 || code >= 300) {
230	      try {
231	        // Buffer the entire body to avoid future I/O.
232	        ResponseBody bufferedBody = Utils.buffer(rawBody);
233	        return Response.error(bufferedBody, rawResponse);
234	      } finally {
235	        rawBody.close();
236	      }
237	    }
238	
239	    if (code == 204 || code == 205) {
240	      rawBody.close();
241	      return Response.success(null, rawResponse);
242	    }
243	
244	    ExceptionCatchingResponseBody catchingBody = new ExceptionCatchingResponseBody(rawBody);
245	    try {
246	      T body = responseConverter.convert(catchingBody);
247	      return Response.success(body, rawResponse);
248	    } catch (RuntimeException e) {
249	      // If the underlying source threw an exception, propagate that rather than indicating it was
250	      // a runtime exception.
251	      catchingBody.throwIfCaught();
252	      throw e;
253	    }
254	  }
255	
256	  @Override
257	  public void cancel() {
258	    canceled = true;
259	
260	    okhttp3.Call call;
261	    synchronized (this) {
262	      call = rawCall;
263	    }
264	    if (call != null) {
265	      call.cancel();
266	    }
267	  }
268	
269	  @Override
270	  public boolean isCanceled() {
271	    if (canceled) {
272	      return true;
273	    }
274	    synchronized (this) {
275	      return rawCall != null && rawCall.isCanceled();
276	    }
277	  }
