279	  static final class NoContentResponseBody extends ResponseBody {
280	    private final @Nullable MediaType contentType;
281	    private final long contentLength;
282	
283	    NoContentResponseBody(@Nullable MediaType contentType, long contentLength) {
284	      this.contentType = contentType;
285	      this.contentLength = contentLength;
286	    }
287	
288	    @Override
289	    public MediaType contentType() {
290	      return contentType;
291	    }
292	
293	    @Override
294	    public long contentLength() {
