304	  static final class ExceptionCatchingResponseBody extends ResponseBody {
305	    private final ResponseBody delegate;
306	    private final BufferedSource delegateSource;
307	    @Nullable IOException thrownException;
308	
309	    ExceptionCatchingResponseBody(ResponseBody delegate) {
310	      this.delegate = delegate;
311	      this.delegateSource =
312	          Okio.buffer(
313	              new ForwardingSource(delegate.source()) {
314	                @Override
315	                public long read(Buffer sink, long byteCount) throws IOException {
316	                  try {
317	                    return super.read(sink, byteCount);
318	                  } catch (IOException e) {
319	                    thrownException = e;
320	                    throw e;
321	                  }
322	                }
323	              });
324	    }
325	
326	    @Override
327	    public MediaType contentType() {
328	      return delegate.contentType();
329	    }
330	
331	    @Override
332	    public long contentLength() {
333	      return delegate.contentLength();
334	    }
335	
336	    @Override
337	    public BufferedSource source() {
338	      return delegateSource;
339	    }
340	
341	    @Override
342	    public void close() {
343	      delegate.close();
344	    }
345	
346	    void throwIfCaught() throws IOException {
347	      if (thrownException != null) {
348	        throw thrownException;
349	      }
350	    }
351	  }
