127	   * instances. A {@link RequestBody} can also be used for a raw representation.
128	   *
129	   * <p>Alternative request body formats are supported by method annotations and corresponding
130	   * parameter annotations:
131	   *
132	   * <ul>
133	   *   <li>{@link retrofit2.http.FormUrlEncoded @FormUrlEncoded} - Form-encoded data with key-value
134	   *       pairs specified by the {@link retrofit2.http.Field @Field} parameter annotation.
135	   *   <li>{@link retrofit2.http.Multipart @Multipart} - RFC 2388-compliant multipart data with
136	   *       parts specified by the {@link retrofit2.http.Part @Part} parameter annotation.
137	   * </ul>
138	   *
139	   * <p>Additional static headers can be added for an endpoint using the {@link
140	   * retrofit2.http.Headers @Headers} method annotation. For per-request control over a header
141	   * annotate a parameter with {@link Header @Header}.
142	   *
143	   * <p>By default, methods return a {@link Call} which represents the HTTP request. The generic
144	   * parameter of the call is the response body type and will be converted by one of the {@link
145	   * Converter.Factory} instances. {@link ResponseBody} can also be used for a raw representation.
146	   * {@link Void} can be used if you do not care about the body contents.
147	   *
148	   * <p>For example:
149	   *
150	   * <pre>
151	   * public interface CategoryService {
152	   *   &#64;POST("category/{cat}/")
153	   *   Call&lt;List&lt;Item&gt;&gt; categoryList(@Path("cat") String a, @Query("page") int b);
154	   * }
155	   * </pre>
156	   */
157	  @SuppressWarnings("unchecked") // Single-interface proxy creation guarded by parameter safety.
158	  public <T> T create(final Class<T> service) {
159	    validateServiceInterface(service);
160	    return (T)
161	        Proxy.newProxyInstance(
162	            service.getClassLoader(),
163	            new Class<?>[] {service},
164	            new InvocationHandler() {
165	              private final Object[] emptyArgs = new Object[0];
166	
167	              @Override
168	              public @Nullable Object invoke(Object proxy, Method method, @Nullable Object[] args)
169	                  throws Throwable {
170	                // If the method is a method from Object then defer to normal invocation.
171	                if (method.getDeclaringClass() == Object.class) {
172	                  return method.invoke(this, args);
173	                }
174	                args = args != null ? args : emptyArgs;
175	                Reflection reflection = Platform.reflection;
176	                return reflection.isDefaultMethod(method)
177	                    ? reflection.invokeDefaultMethod(method, service, proxy, args)
178	                    : loadServiceMethod(service, method).invoke(proxy, args);
179	              }
180	            });
181	  }
182	
183	  private void validateServiceInterface(Class<?> service) {
184	    if (!service.isInterface()) {
185	      throw new IllegalArgumentException("API declarations must be interfaces.");
186	    }
187	
188	    Deque<Class<?>> check = new ArrayDeque<>(1);
189	    check.add(service);
190	    while (!check.isEmpty()) {
191	      Class<?> candidate = check.removeFirst();
192	      if (candidate.getTypeParameters().length != 0) {
193	        StringBuilder message =
194	            new StringBuilder("Type parameters are unsupported on ").append(candidate.getName());
195	        if (candidate != service) {
196	          message.append(" which is an interface of ").append(service.getName());
197	        }
198	        throw new IllegalArgumentException(message.toString());
199	      }
200	      Collections.addAll(check, candidate.getInterfaces());
201	    }
202	
203	    if (validateEagerly) {
204	      Reflection reflection = Platform.reflection;
205	      for (Method method : service.getDeclaredMethods()) {
206	        if (!reflection.isDefaultMethod(method)
207	            && !Modifier.isStatic(method.getModifiers())
208	            && !method.isSynthetic()) {
209	          loadServiceMethod(service, method);
210	        }
211	      }
212	    }
213	  }
214	
215	  ServiceMethod<?> loadServiceMethod(Class<?> service, Method method) {
216	    while (true) {
217	      // Note: Once we are minSdk 24 this whole method can be replaced by computeIfAbsent.
218	      Object lookup = serviceMethodCache.get(method);
219	
220	      if (lookup instanceof ServiceMethod<?>) {
221	        // Happy path: method is already parsed into the model.
222	        return (ServiceMethod<?>) lookup;
223	      }
224	
225	      if (lookup == null) {
226	        // Map does not contain any value. Try to put in a lock for this method. We MUST synchronize
227	        // on the lock before it is visible to others via the map to signal we are doing the work.
228	        Object lock = new Object();
229	        synchronized (lock) {
230	          lookup = serviceMethodCache.putIfAbsent(method, lock);
231	          if (lookup == null) {
232	            // On successful lock insertion, perform the work and update the map before releasing.
233	            // Other threads may be waiting on lock now and will expect the parsed model.
234	            ServiceMethod<Object> result;
235	            try {
236	              result = ServiceMethod.parseAnnotations(this, service, method);
237	            } catch (Throwable e) {
238	              // Remove the lock on failure. Any other locked threads will retry as a result.
239	              serviceMethodCache.remove(method);
240	              throw e;
241	            }
242	            serviceMethodCache.put(method, result);
243	            return result;
244	          }
245	        }
246	      }
247	
248	      // Either the initial lookup or the attempt to put our lock in the map has returned someone
249	      // else's lock. This means they are doing the parsing, and will update the map before
250	      // releasing
251	      // the lock. Once we can take the lock, the map is guaranteed to contain the model or null.
252	      // Note: There's a chance that our effort to put a lock into the map has actually returned a
253	      // finished model instead of a lock. In that case this code will perform a pointless lock and
254	      // redundant lookup in the map of the same instance. This is rare, and ultimately harmless.
255	      synchronized (lookup) {
256	        Object result = serviceMethodCache.get(method);
257	        if (result == null) {
258	          // The other thread failed its parsing. We will retry (and probably also fail).
259	          continue;
260	        }
261	        return (ServiceMethod<?>) result;
262	      }
263	    }
264	  }
