558	    /**
559	     * Set the API base URL.
560	     *
561	     * <p>The specified endpoint values (such as with {@link GET @GET}) are resolved against this
562	     * value using {@link HttpUrl#resolve(String)}. The behavior of this matches that of an {@code
563	     * <a href="">} link on a website resolving on the current URL.
564	     *
565	     * <p><b>Base URLs should always end in {@code /}.</b>
566	     *
567	     * <p>A trailing {@code /} ensures that endpoints values which are relative paths will correctly
568	     * append themselves to a base which has path components.
569	     *
570	     * <p><b>Correct:</b><br>
571	     * Base URL: http://example.com/api/<br>
572	     * Endpoint: foo/bar/<br>
573	     * Result: http://example.com/api/foo/bar/
574	     *
575	     * <p><b>Incorrect:</b><br>
576	     * Base URL: http://example.com/api<br>
577	     * Endpoint: foo/bar/<br>
578	     * Result: http://example.com/foo/bar/
579	     *
580	     * <p>This method enforces that {@code baseUrl} has a trailing {@code /}.
581	     *
582	     * <p><b>Endpoint values which contain a leading {@code /} are absolute.</b>
583	     *
584	     * <p>Absolute values retain only the host from {@code baseUrl} and ignore any specified path
585	     * components.
586	     *
587	     * <p>Base URL: http://example.com/api/<br>
588	     * Endpoint: /foo/bar/<br>
589	     * Result: http://example.com/foo/bar/
590	     *
591	     * <p>Base URL: http://example.com/<br>
592	     * Endpoint: /foo/bar/<br>
593	     * Result: http://example.com/foo/bar/
594	     *
595	     * <p><b>Endpoint values may be a full URL.</b>
596	     *
597	     * <p>Values which have a host replace the host of {@code baseUrl} and values also with a scheme
598	     * replace the scheme of {@code baseUrl}.
599	     *
600	     * <p>Base URL: http://example.com/<br>
601	     * Endpoint: https://github.com/lysine-dev/retrofit/<br>
602	     * Result: https://github.com/lysine-dev/retrofit/
603	     *
604	     * <p>Base URL: http://example.com<br>
605	     * Endpoint: //github.com/lysine-dev/retrofit/<br>
606	     * Result: http://github.com/lysine-dev/retrofit/ (note the scheme stays 'http')
607	     */
608	    public Builder baseUrl(HttpUrl baseUrl) {
609	      Objects.requireNonNull(baseUrl, "baseUrl == null");
610	      List<String> pathSegments = baseUrl.pathSegments();
611	      if (!"".equals(pathSegments.get(pathSegments.size() - 1))) {
612	        throw new IllegalArgumentException("baseUrl must end in /: " + baseUrl);
613	      }
614	      this.baseUrl = baseUrl;
615	      return this;
616	    }
