30	/** Adapts an invocation of an interface method into an HTTP call. */
31	abstract class HttpServiceMethod<ResponseT, ReturnT> extends ServiceMethod<ReturnT> {
32	  /**
33	   * Inspects the annotations on an interface method to construct a reusable service method that
34	   * speaks HTTP. This requires potentially-expensive reflection so it is best to build each service
35	   * method only once and reuse it.
36	   */
37	  static <ResponseT, ReturnT> HttpServiceMethod<ResponseT, ReturnT> parseAnnotations(
38	      Retrofit retrofit, Method method, RequestFactory requestFactory) {
39	    boolean isKotlinSuspendFunction = requestFactory.isKotlinSuspendFunction;
40	    boolean continuationWantsResponse = false;
41	    boolean continuationBodyNullable = false;
42	    boolean continuationIsUnit = false;
43	
44	    Annotation[] annotations = method.getAnnotations();
45	    Type adapterType;
46	    if (isKotlinSuspendFunction) {
47	      Type[] parameterTypes = method.getGenericParameterTypes();
48	      Type responseType =
49	          Utils.getParameterLowerBound(
50	              0, (ParameterizedType) parameterTypes[parameterTypes.length - 1]);
51	      if (getRawType(responseType) == Response.class && responseType instanceof ParameterizedType) {
52	        // Unwrap the actual body type from Response<T>.
53	        responseType = Utils.getParameterUpperBound(0, (ParameterizedType) responseType);
54	        continuationWantsResponse = true;
55	      } else {
56	        if (getRawType(responseType) == Call.class) {
57	          throw methodError(
58	              method,
59	              "Suspend functions should not return Call, as they already execute asynchronously.\n"
60	                  + "Change its return type to %s",
61	              Utils.getParameterUpperBound(0, (ParameterizedType) responseType));
62	        }
63	
64	        continuationIsUnit = Utils.isUnit(responseType);
65	        // TODO figure out if type is nullable or not
66	        // Metadata metadata = method.getDeclaringClass().getAnnotation(Metadata.class)
67	        // Find the entry for method
68	        // Determine if return type is nullable or not
69	      }
70	
71	      adapterType = new Utils.ParameterizedTypeImpl(null, Call.class, responseType);
72	      annotations = SkipCallbackExecutorImpl.ensurePresent(annotations);
73	    } else {
74	      adapterType = method.getGenericReturnType();
75	    }
76	
77	    CallAdapter<ResponseT, ReturnT> callAdapter =
78	        createCallAdapter(retrofit, method, adapterType, annotations);
79	    Type responseType = callAdapter.responseType();
80	    if (responseType == okhttp3.Response.class) {
81	      throw methodError(
82	          method,
83	          "'"
84	              + getRawType(responseType).getName()
85	              + "' is not a valid response body type. Did you mean ResponseBody?");
86	    }
87	    if (responseType == Response.class) {
88	      throw methodError(method, "Response must include generic type (e.g., Response<String>)");
89	    }
90	    if (requestFactory.httpMethod.equals("HEAD")
91	        && !Void.class.equals(responseType)
92	        && !Utils.isUnit(responseType)) {
93	      throw methodError(method, "HEAD method must use Void or Unit as response type.");
94	    }
95	
96	    Converter<ResponseBody, ResponseT> responseConverter =
97	        createResponseConverter(retrofit, method, responseType);
98	
99	    okhttp3.Call.Factory callFactory = retrofit.callFactory;
100	    if (!isKotlinSuspendFunction) {
101	      return new CallAdapted<>(requestFactory, callFactory, responseConverter, callAdapter);
102	    } else if (continuationWantsResponse) {
103	      //noinspection unchecked Kotlin compiler guarantees ReturnT to be Object.
104	      return (HttpServiceMethod<ResponseT, ReturnT>)
105	          new SuspendForResponse<>(
106	              requestFactory,
107	              callFactory,
108	              responseConverter,
109	              (CallAdapter<ResponseT, Call<ResponseT>>) callAdapter);
110	    } else {
111	      //noinspection unchecked Kotlin compiler guarantees ReturnT to be Object.
112	      return (HttpServiceMethod<ResponseT, ReturnT>)
113	          new SuspendForBody<>(
114	              requestFactory,
115	              callFactory,
116	              responseConverter,
117	              (CallAdapter<ResponseT, Call<ResponseT>>) callAdapter,
118	              continuationBodyNullable,
119	              continuationIsUnit);
120	    }
121	  }
122	
123	  private static <ResponseT, ReturnT> CallAdapter<ResponseT, ReturnT> createCallAdapter(
124	      Retrofit retrofit, Method method, Type returnType, Annotation[] annotations) {
125	    try {
126	      //noinspection unchecked
127	      return (CallAdapter<ResponseT, ReturnT>) retrofit.callAdapter(returnType, annotations);
128	    } catch (RuntimeException e) { // Wide exception range because factories are user code.
129	      throw methodError(method, e, "Unable to create call adapter for %s", returnType);
130	    }
131	  }
132	
133	  private static <ResponseT> Converter<ResponseBody, ResponseT> createResponseConverter(
134	      Retrofit retrofit, Method method, Type responseType) {
135	    Annotation[] annotations = method.getAnnotations();
136	    try {
137	      return retrofit.responseBodyConverter(responseType, annotations);
138	    } catch (RuntimeException e) { // Wide exception range because factories are user code.
139	      throw methodError(method, e, "Unable to create converter for %s", responseType);
140	    }
141	  }
142	
143	  private final RequestFactory requestFactory;
144	  private final okhttp3.Call.Factory callFactory;
145	  private final Converter<ResponseBody, ResponseT> responseConverter;
146	
147	  HttpServiceMethod(
148	      RequestFactory requestFactory,
149	      okhttp3.Call.Factory callFactory,
150	      Converter<ResponseBody, ResponseT> responseConverter) {
151	    this.requestFactory = requestFactory;
152	    this.callFactory = callFactory;
153	    this.responseConverter = responseConverter;
154	  }
155	
156	  @Override
157	  final @Nullable ReturnT invoke(Object instance, Object[] args) {
158	    Call<ResponseT> call =
159	        new OkHttpCall<>(requestFactory, instance, args, callFactory, responseConverter);
160	    return adapt(call, args);
161	  }
162	
163	  protected abstract @Nullable ReturnT adapt(Call<ResponseT> call, Object[] args);
164	
165	  static final class CallAdapted<ResponseT, ReturnT> extends HttpServiceMethod<ResponseT, ReturnT> {
166	    private final CallAdapter<ResponseT, ReturnT> callAdapter;
167	
168	    CallAdapted(
169	        RequestFactory requestFactory,
170	        okhttp3.Call.Factory callFactory,
171	        Converter<ResponseBody, ResponseT> responseConverter,
172	        CallAdapter<ResponseT, ReturnT> callAdapter) {
173	      super(requestFactory, callFactory, responseConverter);
174	      this.callAdapter = callAdapter;
175	    }
176	
177	    @Override
178	    protected ReturnT adapt(Call<ResponseT> call, Object[] args) {
179	      return callAdapter.adapt(call);
180	    }
181	  }
182	
183	  static final class SuspendForResponse<ResponseT> extends HttpServiceMethod<ResponseT, Object> {
184	    private final CallAdapter<ResponseT, Call<ResponseT>> callAdapter;
185	
186	    SuspendForResponse(
187	        RequestFactory requestFactory,
188	        okhttp3.Call.Factory callFactory,
189	        Converter<ResponseBody, ResponseT> responseConverter,
190	        CallAdapter<ResponseT, Call<ResponseT>> callAdapter) {
191	      super(requestFactory, callFactory, responseConverter);
192	      this.callAdapter = callAdapter;
193	    }
194	
195	    @Override
196	    protected Object adapt(Call<ResponseT> call, Object[] args) {
197	      call = callAdapter.adapt(call);
198	
199	      //noinspection unchecked Checked by reflection inside RequestFactory.
200	      Continuation<Response<ResponseT>> continuation =
201	          (Continuation<Response<ResponseT>>) args[args.length - 1];
202	
203	      // See SuspendForBody for explanation about this try/catch.
204	      try {
205	        return KotlinExtensions.awaitResponse(call, continuation);
206	      } catch (Exception e) {
207	        return KotlinExtensions.suspendAndThrow(e, continuation);
208	      }
209	    }
210	  }
211	
212	  static final class SuspendForBody<ResponseT> extends HttpServiceMethod<ResponseT, Object> {
213	    private final CallAdapter<ResponseT, Call<ResponseT>> callAdapter;
214	    private final boolean isNullable;
215	    private final boolean isUnit;
216	
217	    SuspendForBody(
218	        RequestFactory requestFactory,
219	        okhttp3.Call.Factory callFactory,
220	        Converter<ResponseBody, ResponseT> responseConverter,
221	        CallAdapter<ResponseT, Call<ResponseT>> callAdapter,
222	        boolean isNullable,
223	        boolean isUnit) {
224	      super(requestFactory, callFactory, responseConverter);
225	      this.callAdapter = callAdapter;
226	      this.isNullable = isNullable;
227	      this.isUnit = isUnit;
228	    }
229	
230	    @Override
231	    @SuppressWarnings("removal") // ThreadDeath still available on supported JDKs.
232	    protected Object adapt(Call<ResponseT> call, Object[] args) {
233	      call = callAdapter.adapt(call);
234	
235	      //noinspection unchecked Checked by reflection inside RequestFactory.
236	      Continuation<ResponseT> continuation = (Continuation<ResponseT>) args[args.length - 1];
237	
238	      // Calls to OkHttp Call.enqueue() like those inside await and awaitNullable can sometimes
239	      // invoke the supplied callback with an exception before the invoking stack frame can return.
240	      // Coroutines will intercept the subsequent invocation of the Continuation and throw the
241	      // exception synchronously. A Java Proxy cannot throw checked exceptions without them being
242	      // declared on the interface method. To avoid the synchronous checked exception being wrapped
243	      // in an UndeclaredThrowableException, it is intercepted and supplied to a helper which will
244	      // force suspension to occur so that it can be instead delivered to the continuation to
245	      // bypass this restriction.
246	      try {
247	        if (isUnit) {
248	          //noinspection unchecked Checked by isUnit
249	          return KotlinExtensions.awaitUnit((Call<Unit>) call, (Continuation<Unit>) continuation);
250	        } else if (isNullable) {
251	          return KotlinExtensions.awaitNullable(call, continuation);
252	        } else {
253	          return KotlinExtensions.await(call, continuation);
254	        }
255	      } catch (VirtualMachineError | ThreadDeath | LinkageError e) {
256	        // Do not attempt to capture fatal throwables. This list is derived RxJava's `throwIfFatal`.
257	        throw e;
258	      } catch (Throwable e) {
259	        return KotlinExtensions.suspendAndThrow(e, continuation);
260	      }
261	    }
262	  }
263	}
