71	  static Class<?> getRawType(Type type) {
72	    Objects.requireNonNull(type, "type == null");
73	
74	    if (type instanceof Class<?>) {
75	      // Type is a normal class.
76	      return (Class<?>) type;
77	    }
78	    if (type instanceof ParameterizedType) {
79	      ParameterizedType parameterizedType = (ParameterizedType) type;
80	
81	      // I'm not exactly sure why getRawType() returns Type instead of Class. Neal isn't either but
82	      // suspects some pathological case related to nested classes exists.
83	      Type rawType = parameterizedType.getRawType();
84	      if (!(rawType instanceof Class)) throw new IllegalArgumentException();
85	      return (Class<?>) rawType;
86	    }
87	    if (type instanceof GenericArrayType) {
88	      Type componentType = ((GenericArrayType) type).getGenericComponentType();
89	      return Array.newInstance(getRawType(componentType), 0).getClass();
90	    }
91	    if (type instanceof TypeVariable) {
92	      // We could use the variable's bounds, but that won't work if there are multiple. Having a raw
93	      // type that's more general than necessary is okay.
94	      return Object.class;
95	    }
96	    if (type instanceof WildcardType) {
97	      return getRawType(((WildcardType) type).getUpperBounds()[0]);
98	    }
99	
100	    throw new IllegalArgumentException(
101	        "Expected a Class, ParameterizedType, or "
102	            + "GenericArrayType, but <"
103	            + type
104	            + "> is of type "
105	            + type.getClass().getName());
106	  }
107	
108	  /** Returns true if {@code a} and {@code b} are equal. */
109	  static boolean equals(Type a, Type b) {
110	    if (a == b) {
111	      return true; // Also handles (a == null && b == null).
112	
113	    } else if (a instanceof Class) {
114	      return a.equals(b); // Class already specifies equals().
115	
116	    } else if (a instanceof ParameterizedType) {
117	      if (!(b instanceof ParameterizedType)) return false;
118	      ParameterizedType pa = (ParameterizedType) a;
119	      ParameterizedType pb = (ParameterizedType) b;
120	      Object ownerA = pa.getOwnerType();
121	      Object ownerB = pb.getOwnerType();
122	      boolean ownersAreEqual = ownerA == ownerB || (ownerA != null && ownerA.equals(ownerB));
123	      boolean rawTypesAreEqual = pa.getRawType().equals(pb.getRawType());
124	      boolean typeArgumentsAreEqual =
125	          Arrays.equals(pa.getActualTypeArguments(), pb.getActualTypeArguments());
126	
127	      return ownersAreEqual && rawTypesAreEqual && typeArgumentsAreEqual;
128	
129	    } else if (a instanceof GenericArrayType) {
130	      if (!(b instanceof GenericArrayType)) return false;
131	      GenericArrayType ga = (GenericArrayType) a;
132	      GenericArrayType gb = (GenericArrayType) b;
133	      return equals(ga.getGenericComponentType(), gb.getGenericComponentType());
134	
135	    } else if (a instanceof WildcardType) {
136	      if (!(b instanceof WildcardType)) return false;
137	      WildcardType wa = (WildcardType) a;
138	      WildcardType wb = (WildcardType) b;
139	      return Arrays.equals(wa.getUpperBounds(), wb.getUpperBounds())
140	          && Arrays.equals(wa.getLowerBounds(), wb.getLowerBounds());
141	
142	    } else if (a instanceof TypeVariable) {
143	      if (!(b instanceof TypeVariable)) return false;
144	      TypeVariable<?> va = (TypeVariable<?>) a;
145	      TypeVariable<?> vb = (TypeVariable<?>) b;
146	      return va.getGenericDeclaration() == vb.getGenericDeclaration()
147	          && va.getName().equals(vb.getName());
148	
149	    } else {
150	      return false; // This isn't a type we support!
151	    }
152	  }
153	
154	  /**
155	   * Returns the generic supertype for {@code supertype}. For example, given a class {@code
156	   * IntegerSet}, the result for when supertype is {@code Set.class} is {@code Set<Integer>} and the
157	   * result when the supertype is {@code Collection.class} is {@code Collection<Integer>}.
158	   */
159	  static Type getGenericSupertype(Type context, Class<?> rawType, Class<?> toResolve) {
160	    if (toResolve == rawType) return context;
161	
162	    // We skip searching through interfaces if unknown is an interface.
163	    if (toResolve.isInterface()) {
164	      Class<?>[] interfaces = rawType.getInterfaces();
165	      for (int i = 0, length = interfaces.length; i < length; i++) {
166	        if (interfaces[i] == toResolve) {
167	          return rawType.getGenericInterfaces()[i];
168	        } else if (toResolve.isAssignableFrom(interfaces[i])) {
169	          return getGenericSupertype(rawType.getGenericInterfaces()[i], interfaces[i], toResolve);
170	        }
171	      }
172	    }
173	
174	    // Check our supertypes.
175	    if (!rawType.isInterface()) {
176	      while (rawType != Object.class) {
177	        Class<?> rawSupertype = rawType.getSuperclass();
178	        if (rawSupertype == toResolve) {
179	          return rawType.getGenericSuperclass();
180	        } else if (toResolve.isAssignableFrom(rawSupertype)) {
181	          return getGenericSupertype(rawType.getGenericSuperclass(), rawSupertype, toResolve);
182	        }
183	        rawType = rawSupertype;
184	      }
185	    }
186	
187	    // We can't resolve this further.
188	    return toResolve;
189	  }
