287	  private static Type resolveTypeVariable(
288	      Type context, Class<?> contextRawType, TypeVariable<?> unknown) {
289	    Class<?> declaredByRaw = declaringClassOf(unknown);
290	
291	    // We can't reduce this further.
292	    if (declaredByRaw == null) return unknown;
293	
294	    Type declaredBy = getGenericSupertype(context, contextRawType, declaredByRaw);
295	    if (declaredBy instanceof ParameterizedType) {
296	      int index = indexOf(declaredByRaw.getTypeParameters(), unknown);
297	      return ((ParameterizedType) declaredBy).getActualTypeArguments()[index];
298	    }
299	
300	    return unknown;
301	  }
