303	  /**
304	   * Returns the declaring class of {@code typeVariable}, or {@code null} if it was not declared by
305	   * a class.
306	   */
307	  private static @Nullable Class<?> declaringClassOf(TypeVariable<?> typeVariable) {
308	    GenericDeclaration genericDeclaration = typeVariable.getGenericDeclaration();
309	    return genericDeclaration instanceof Class ? (Class<?>) genericDeclaration : null;
310	  }
