334	  static Type getParameterUpperBound(int index, ParameterizedType type) {
335	    Type[] types = type.getActualTypeArguments();
336	    if (index < 0 || index >= types.length) {
337	      throw new IllegalArgumentException(
338	          "Index " + index + " not in range [0," + types.length + ") for " + type);
339	    }
340	    Type paramType = types[index];
341	    if (paramType instanceof WildcardType) {
342	      return ((WildcardType) paramType).getUpperBounds()[0];
343	    }
344	    return paramType;
345	  }
