 * type. {@code annotationName} (e.g. {@code "@QueryMap"}) labels the "keys must be of type
 * String" error, and {@code mustBeMapMessage} is thrown when the type is not a {@code Map}.
 */
private Type mapValueType(int p, Type type, String annotationName, String mustBeMapMessage) {
  Class<?> rawParameterType = Utils.getRawType(type);
  if (!Map.class.isAssignableFrom(rawParameterType)) {
    throw parameterError(method, p, mustBeMapMessage);
  }
  Type mapType = Utils.getSupertype(type, rawParameterType, Map.class);
  if (!(mapType instanceof ParameterizedType)) {
    throw parameterError(
        method, p, "Map must include generic types (e.g., Map<String, String>)");
  }
